const tree = $('Get Tree').first().json.tree;

const PAGES_EN = 'src/content/pages/en/';
const PAGES_JA = 'src/content/pages/ja/';

const jaPaths = new Set(
  tree
    .filter(f => f.type === 'blob' && f.path.startsWith(PAGES_JA) && f.path.endsWith('.md'))
    .map(f => f.path)
);

const missing = tree
  .filter(f =>
    f.type === 'blob' &&
    f.path.startsWith(PAGES_EN) &&
    f.path.endsWith('.md')
  )
  .filter(f => {
    const jaPath = f.path.replace(PAGES_EN, PAGES_JA);
    return !jaPaths.has(jaPath);
  })
  .map(f => ({
    json: {
      en_path: f.path,
      ja_path: f.path.replace(PAGES_EN, PAGES_JA)
    }
  }));

if (missing.length === 0) {
  return [{ json: { status: 'nothing to translate' } }];
}

return missing;

let translated = $json.response;
const jaPath = $('Build Pages Prompt').item.json.ja_path;

// Sanity-fix the frontmatter delimiters before committing.
// Strip any markdown/yaml code-fence wrapper the model may add.
translated = translated.replace(/^\s*```(?:markdown|md|yaml)?\s*\n/i, '');
translated = translated.replace(/\n```\s*$/i, '\n');
// Drop leading blank lines so the startsWith check isn't fooled.
translated = translated.replace(/^[\r\n]+/, '');
// Restore the opening --- if the model dropped it (~5% of files in early runs).
if (!translated.startsWith('---')) {
  translated = '---\n' + translated;
}
// Ensure a closing --- exists somewhere after the opening.
// If the file has an HTML body (line starting with '<' at col 0), insert --- before it.
// Otherwise (pure section-driven page), append --- at the end of file.
{
  const lines = translated.split('\n');
  let hasClose = false;
  for (let i = 1; i < lines.length; i++) {
    if (lines[i] === '---') { hasClose = true; break; }
  }
  if (!hasClose) {
    let inserted = false;
    for (let i = 1; i < lines.length; i++) {
      if (/^</.test(lines[i])) {
        lines.splice(i, 0, '---');
        inserted = true;
        break;
      }
    }
    if (!inserted) {
      if (lines[lines.length - 1] !== '') lines.push('');
      lines.push('---');
    }
    translated = lines.join('\n');
  }
}

// Repair YAML quote-mismatch issues in frontmatter scalars (LLM
// occasionally emits unparseable YAML when values contain inline HTML).
{
  const fmEnd = translated.indexOf('\n---', 3);
  if (fmEnd !== -1) {
    const fm = translated.slice(0, fmEnd);
    const rest = translated.slice(fmEnd);
    const reQuote = (v) => {
      if (v.includes('"') && !v.includes("'")) {
        return "'" + v.replace(/'/g, "''") + "'";
      }
      return JSON.stringify(v);
    };
    const repaired = fm.split('\n').map((line) => {
      const m = line.match(/^(\s*(?:-\s+)?[\w-]+:\s*)(['"])(.*)(['"])(\s*(?:#.*)?)$/);
      if (!m) return line;
      const [, prefix, openQ, value, closeQ, suffix] = m;
      if (openQ !== closeQ) return prefix + reQuote(value) + suffix;
      if (openQ === '"' && /(?:^|[^\\])"/.test(value)) return prefix + reQuote(value) + suffix;
      if (openQ === "'" && /(?:^|[^'])'(?:[^']|$)/.test(value)) return prefix + reQuote(value) + suffix;
      return line;
    }).join('\n');
    translated = repaired + rest;
  }
}

const encoded = Buffer.from(translated, 'utf-8').toString('base64');

return {
  json: {
    ja_path: jaPath,
    encoded_content: encoded,
    commit_message: 'translate(pages): ' + jaPath + ' [skip ci]'
  }
};

const enYaml = Buffer.from($('Get EN i18n').first().json.content, 'base64').toString('utf-8');
const jaResp = $('Get JA i18n').first().json;
const jaYaml = Buffer.from(jaResp.content, 'base64').toString('utf-8');
const jaSha = jaResp.sha;

function extractStrings(text) {
  const out = {};
  const stack = [];
  for (const rawLine of text.split('\n')) {
    const line = rawLine.replace(/\r$/, '');
    if (!line.trim() || line.trim().startsWith('#')) continue;
    const indent = (line.match(/^(\s*)/) || ['',''])[1].length;
    while (stack.length && stack[stack.length-1].indent >= indent) stack.pop();

    const objMatch = line.match(/^\s*([\w-]+):\s*(?:#.*)?$/);
    if (objMatch) {
      stack.push({ indent, key: objMatch[1] });
      continue;
    }
    const dqMatch = line.match(/^\s*([\w-]+):\s*"((?:[^"\\]|\\.)*)"\s*(?:#.*)?$/);
    if (dqMatch) {
      const fullPath = [...stack.map(s => s.key), dqMatch[1]].join('.');
      try { out[fullPath] = JSON.parse('"' + dqMatch[2] + '"'); } catch (e) { out[fullPath] = dqMatch[2]; }
      continue;
    }
    const sqMatch = line.match(/^\s*([\w-]+):\s*'((?:[^']|'')*)'\s*(?:#.*)?$/);
    if (sqMatch) {
      const fullPath = [...stack.map(s => s.key), sqMatch[1]].join('.');
      out[fullPath] = sqMatch[2].replace(/''/g, "'");
      continue;
    }
  }
  return out;
}

const enStrings = extractStrings(enYaml);
const jaStrings = extractStrings(jaYaml);

const missing = {};
for (const [path, val] of Object.entries(enStrings)) {
  if (!(path in jaStrings)) missing[path] = val;
}

const requested_keys = Object.keys(missing);

return {
  json: {
    en_yaml: enYaml,
    ja_yaml: jaYaml,
    ja_sha: jaSha,
    missing,
    requested_keys,
    has_missing: requested_keys.length > 0,
    missing_count: requested_keys.length
  }
};

const ollamaItem = $('Call Ollama (i18n)').first().json;
const ollamaResp = ollamaItem.response;
const doneReason = ollamaItem.done_reason;
const en_yaml = $('Build i18n Prompt').first().json.en_yaml;
const ja_yaml = $('Build i18n Prompt').first().json.ja_yaml;
const ja_sha  = $('Build i18n Prompt').first().json.ja_sha;
const requested = $('Build i18n Prompt').first().json.requested_keys;

function extractJsonObject(text) {
  if (typeof text !== 'string' || text.trim() === '') {
    throw new Error('Ollama returned an empty response. If you are using a reasoning model (gpt-oss, deepseek-r1, qwq), it likely consumed the output budget on internal reasoning. Try a non-reasoning model (gemma3:27b, qwen2.5:32b, mistral-small:24b) or raise num_predict.');
  }
  if (doneReason === 'length') {
    throw new Error('Ollama output was truncated (done_reason=length, ' + text.length + ' chars emitted). The current num_predict (16384) was too low for ' + requested.length + ' keys. Bump options.num_predict in Call Ollama (i18n), or split into smaller batches.');
  }
  try { return JSON.parse(text); } catch (_) {}
  const stripped = text.replace(/^[\s\S]*?```(?:json)?\s*/i, '').replace(/```[\s\S]*$/i, '').trim();
  if (stripped) {
    try { return JSON.parse(stripped); } catch (_) {}
  }
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try { return JSON.parse(text.slice(first, last + 1)); } catch (_) {}
  }
  throw new Error('Could not parse JSON from Ollama response. done_reason=' + doneReason + '. First 500 chars: ' + text.slice(0, 500));
}

let translations;
try {
  translations = extractJsonObject(ollamaResp);
} catch (e) {
  throw e;
}
if (!translations || typeof translations !== 'object' || Array.isArray(translations)) {
  throw new Error('Ollama response did not parse to a JSON object');
}
const missing = [];
for (const k of requested) {
  if (typeof translations[k] !== 'string') missing.push(k);
}
if (missing.length) {
  throw new Error('Ollama omitted ' + missing.length + ' of ' + requested.length + ' keys: ' + missing.slice(0, 10).join(', ') + (missing.length > 10 ? ` (+${missing.length-10} more)` : ''));
}

function extractStrings(text) {
  const out = {};
  const stack = [];
  for (const rawLine of text.split('\n')) {
    const line = rawLine.replace(/\r$/, '');
    if (!line.trim() || line.trim().startsWith('#')) continue;
    const indent = (line.match(/^(\s*)/) || ['',''])[1].length;
    while (stack.length && stack[stack.length-1].indent >= indent) stack.pop();
    const objMatch = line.match(/^\s*([\w-]+):\s*(?:#.*)?$/);
    if (objMatch) { stack.push({ indent, key: objMatch[1] }); continue; }
    const dqMatch = line.match(/^\s*([\w-]+):\s*"((?:[^"\\]|\\.)*)"\s*(?:#.*)?$/);
    if (dqMatch) {
      const fullPath = [...stack.map(s => s.key), dqMatch[1]].join('.');
      try { out[fullPath] = JSON.parse('"' + dqMatch[2] + '"'); } catch (e) { out[fullPath] = dqMatch[2]; }
      continue;
    }
    const sqMatch = line.match(/^\s*([\w-]+):\s*'((?:[^']|'')*)'\s*(?:#.*)?$/);
    if (sqMatch) {
      const fullPath = [...stack.map(s => s.key), sqMatch[1]].join('.');
      out[fullPath] = sqMatch[2].replace(/''/g, "'");
      continue;
    }
  }
  return out;
}

const existingJa = extractStrings(ja_yaml);

function emitDouble(value) {
  return JSON.stringify(value);
}
function emitSingle(value) {
  return "'" + value.replace(/'/g, "''") + "'";
}

function rebuildYaml(enText, getValue) {
  const lines = enText.split('\n');
  const stack = [];
  const out = [];
  for (const rawLine of lines) {
    const line = rawLine.replace(/\r$/, '');
    if (!line.trim() || line.trim().startsWith('#')) {
      out.push(line);
      continue;
    }
    const indent = (line.match(/^(\s*)/) || ['',''])[1].length;
    while (stack.length && stack[stack.length-1].indent >= indent) stack.pop();
    const objMatch = line.match(/^(\s*)([\w-]+):\s*(?:#.*)?$/);
    if (objMatch) {
      stack.push({ indent, key: objMatch[2] });
      out.push(line);
      continue;
    }
    const dqMatch = line.match(/^(\s*)([\w-]+):\s*"((?:[^"\\]|\\.)*)"(\s*(?:#.*)?)$/);
    if (dqMatch) {
      const fullPath = [...stack.map(s => s.key), dqMatch[2]].join('.');
      const v = getValue(fullPath);
      out.push(`${dqMatch[1]}${dqMatch[2]}: ${emitDouble(v)}${dqMatch[4]}`);
      continue;
    }
    const sqMatch = line.match(/^(\s*)([\w-]+):\s*'((?:[^']|'')*)'(\s*(?:#.*)?)$/);
    if (sqMatch) {
      const fullPath = [...stack.map(s => s.key), sqMatch[2]].join('.');
      const v = getValue(fullPath);
      const useSingle = v.includes('"') && !v.includes("'");
      out.push(`${sqMatch[1]}${sqMatch[2]}: ${useSingle ? emitSingle(v) : emitDouble(v)}${sqMatch[4]}`);
      continue;
    }
    out.push(line);
  }
  return out.join('\n');
}

const newJa = rebuildYaml(en_yaml, (p) => {
  if (typeof translations[p] === 'string') return translations[p];
  if (typeof existingJa[p] === 'string') return existingJa[p];
  // Fallback: should not happen because en strings are either in existing or were requested.
  // Use empty so deepMerge falls back to en at runtime.
  return '';
});

const encoded = Buffer.from(newJa, 'utf-8').toString('base64');

return {
  json: {
    encoded_content: encoded,
    ja_sha,
    commit_message: 'translate(i18n): ja.yml [skip ci]'
  }
};
